// Serve the generated A/B paper HTML and inject the same favorites/progress
// scripts used by the archived exams. The page is generated by
// personal/exams/build.mjs; this endpoint only adds the runtime tags.
import type { APIRoute } from 'astro';
import { readFile } from 'node:fs/promises';
import { withBase } from '../../../src/lib/site-path.mjs';
import { PAPERS } from '../../exams/data/papers.mjs';
import { rewriteAuthorBookLinks } from '../../exams/reader-links.mjs';
import {
  injectExamFavorites,
  injectExamProgress,
  injectNav,
  injectPageAssistant,
} from '../../harness/static.mjs';
import { BOOK_EXAM_PATH } from '../../routes.mjs';

export function getStaticPaths() {
  return Object.keys(PAPERS).map((id) => ({
    params: { paper: id.toLowerCase() },
  }));
}

export const GET: APIRoute = async ({ params }) => {
  const id = String(params.paper ?? '').toUpperCase();
  const paper = Object.values(PAPERS).find((item) => item.id === id);
  if (!paper) {
    return new Response('Not found\n', {
      status: 404,
      headers: { 'content-type': 'text/plain; charset=utf-8' },
    });
  }

  let html = await readFile(new URL(`../../exams/${paper.file}`, import.meta.url), 'utf8');
  // The same file doubles as a standalone page, where 出处 must stay a full URL.
  // Inside the reader, point 出处 at the local chapter routes instead.
  html = rewriteAuthorBookLinks(html);
  html = injectExamProgress(html, {
    exam: paper.examId,
    src: withBase('/harness/exam-progress.js'),
  });
  html = injectExamFavorites(html, {
    exam: paper.examId,
    src: withBase('/harness/exam-favorites.js'),
    favoritesHref: withBase('/harness/favorites/'),
  });
  html = injectPageAssistant(html, {
    src: withBase('/personal/client/page-assistant.ts'),
  });
  // Requirement 010 follow-up: give the generated paper the same bottom-left
  // floating nav as the archived pages, with an exam-specific home link.
  html = injectNav(html, withBase('/'), {
    homeHref: withBase(BOOK_EXAM_PATH),
    homeLabel: '结业考试',
    homeShort: '试卷',
    homeIcon: '▤',
  });

  return new Response(html, {
    status: 200,
    headers: {
      'content-type': 'text/html; charset=utf-8',
      'cache-control': 'no-cache',
      'x-content-type-options': 'nosniff',
    },
  });
};
